package br.pucminas.iceibank.security;
import br.pucminas.iceibank.service.JwtService; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {private final JwtService jwtService; public JwtAuthenticationFilter(JwtService jwtService){this.jwtService=jwtService;} @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String auth=request.getHeader("Authorization");if(auth!=null&&auth.startsWith("Bearer ")){try{String usuario=jwtService.validarEObterClaims(auth.substring(7).trim()).getSubject();if(usuario==null||usuario.isBlank())throw new JwtException("subject ausente");SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(usuario,null,List.of(new SimpleGrantedAuthority("ROLE_USER"))));request.setAttribute("usuarioAutenticado",usuario);}catch(JwtException|IllegalArgumentException e){SecurityContextHolder.clearContext();response.setStatus(401);response.setContentType("application/json;charset=UTF-8");response.getWriter().write("{\"erro\":\"Token JWT inválido ou expirado.\"}");return;}}chain.doFilter(request,response);}}
